import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const sources = [
  'src/logic.mjs',
  'src/renderer.mjs',
  'src/world.mjs',
  'src/audio.mjs',
  'src/game.mjs'
];

function stripImports(source) {
  return source.replace(/^import\s+(?:[\s\S]*?\s+from\s+)?['"][^'"]+['"];?\s*$/gm, '');
}

function stripExports(source) {
  return source
    .replace(/^export\s+default\s+/gm, '')
    .replace(/^export\s+(?=(?:const|let|var|function|class)\b)/gm, '')
    .replace(/^export\s*\{[^}]*\};?\s*$/gm, '');
}

const parts = [];
for (const relative of sources) {
  const source = await readFile(resolve(root, relative), 'utf8');
  parts.push(`\n// ---- ${relative} ----\n${stripExports(stripImports(source)).trim()}\n`);
}

const bundle = `/* Generated by tools/build-player-bundle.mjs. Do not edit directly. */\n(() => {\n'use strict';\n${parts.join('\n')}\n})();\n`;
await writeFile(resolve(root, 'src/game.bundle.js'), bundle, 'utf8');
console.log('Built src/game.bundle.js');
